// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 tsDelta, uint256 nDelta, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        tsDelta = bound(tsDelta, 1, 10_000);
        nDelta = bound(nDelta, 0, 10_000);

        // first successful fallback call at genesis (ts=1, n=1)
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        uint256 stored1 = c.pastBlockTime();

        // move forward: timestamps always advance; block number may advance by any non-negative amount
        vm.warp(block.timestamp + tsDelta);
        vm.roll(block.number + nDelta);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        uint256 stored2 = c.pastBlockTime();
        // General rule: the stored guard strictly increases between consecutive successful calls.
        assertTrue(stored2 > stored1);
    }
}
